                  "sentiment",
                  "expansion",
                  "churn_risk",
                  "timeline",
                  "budget",
                  "decision_maker",
                  "requirements",
                  "blocker",
                  "commitment",
                  "success_criterion",
                  "product_usage",
                  "contact_info",
